#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The secret/variable names CI reads. Pinned here and in issue #258: the
# release workflow must use exactly these names.
GH_ENV="release"
REPO="JohnJohn4/dictatem"
# to_native PATH: on Git Bash, the Windows "C:/..." form, which both bash and
# the native openssl understand. Needed because path conversion is off (below).
to_native() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -m "$1"; else printf '%s' "$1"; fi
}
SIGNING_DIR="$(to_native "${SIGNING_DIR:-$HOME/dictatem-signing}")"
# Values captured along the way live in a private file OUTSIDE the repo, so a
# re-run remembers them. Back the whole folder up offline (stage 7).
ENV_FILE="$SIGNING_DIR/signing.env"
# Git Bash rewrites "/CN=..." style arguments into Windows paths; stop it. Safe
# because every path this wizard hands to a tool is already in native form.
export MSYS_NO_PATHCONV=1

_gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# set_env_secret NAME VALUE: a secret on the protected `release` environment
# (not repo-wide), so only tag-triggered release jobs can read it.
set_env_secret() {
  local name="$1" value="$2"
  if _gh_ready && printf '%s' "$value" | gh secret set "$name" --env "$GH_ENV" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s %s secret %s\n' "$GREEN" "$RESET" "$GH_ENV" "$name"
  else
    SKIPPED+=("$GH_ENV secret $name (gh secret set $name --env $GH_ENV)")
    warn "couldn't set $name; set it later with: gh secret set $name --env $GH_ENV"
  fi
}

set_env_var() {
  local name="$1" value="$2"
  if _gh_ready && gh variable set "$name" --env "$GH_ENV" --repo "$REPO" --body "$value" >/dev/null 2>&1; then
    printf '  %s✓ set%s %s variable %s\n' "$GREEN" "$RESET" "$GH_ENV" "$name"
  else
    SKIPPED+=("$GH_ENV variable $name (gh variable set $name --env $GH_ENV --body ...)")
    warn "couldn't set variable $name"
  fi
}

b64() { base64 < "$1" | tr -d '\n\r'; }

# strip_path "PATH": drop the quotes a drag-and-drop adds around a path.
strip_path() { local p="$1"; p="${p//\"/}"; p="${p//\'/}"; to_native "$p"; }

run_wizard() {

TOTAL_STAGES=11

banner "Dictatem: macOS signing setup (Developer ID + notarization)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "This sets up everything Apple and GitHub need so release builds of Dictatem"
say "are signed and notarized. About 30 minutes once Apple has approved you."
say ""
say "Your private files go in: $SIGNING_DIR  (outside the repo)"
mkdir -p "$SIGNING_DIR"; chmod 700 "$SIGNING_DIR" 2>/dev/null || true
command -v openssl >/dev/null 2>&1 || { warn "openssl not found. Run this in Git Bash (it ships openssl)."; exit 1; }
if _gh_ready; then note "gh is signed in. Good."
else warn "gh isn't signed in. Run 'gh auth login' in another terminal, then continue."
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Apple Developer Program enrollment"
say "Enroll as an Individual (US\$99/yr). You need an Apple ID with two-factor auth."
warn "Individual enrollment puts your LEGAL NAME on the certificate. Users see it"
warn "in macOS security prompts and Login Items. (Organization needs a D-U-N-S number.)"
open_url "https://developer.apple.com/programs/enroll/"
step "Sign in, Start your enrollment, choose Individual / Sole Proprietor, pay."
note "Tip: enrolling in the Apple Developer app on an iPhone is often approved faster."
note "Approval can take up to about 48 hours. You'll get an email."
if ! confirm "Is your enrollment APPROVED (the email has arrived)?"; then
  say "No problem. Re-run this wizard once it's approved; it remembers your answers."
  exit 0
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Your Team ID"
open_url "https://developer.apple.com/account"
step "Scroll to Membership details and copy the 10-character Team ID."
ask TEAM_ID "Paste your Team ID:"
[[ "$TEAM_ID" =~ ^[A-Z0-9]{10}$ ]] || warn "That doesn't look like a 10-character Team ID; double-check it."
write_env TEAM_ID "$TEAM_ID"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create your private key + certificate request"
say "Apple needs a Certificate Signing Request (CSR). This makes one on this PC,"
say "together with the private key that only you will ever hold."
KEY="$SIGNING_DIR/developer-id.key"; CSR="$SIGNING_DIR/developer-id.csr"
if [[ -f "$KEY" ]]; then
  note "A private key already exists ($KEY), so keeping it."
  warn "Never replace it once Apple has issued a certificate for it."
else
  ask CSR_EMAIL "Your Apple ID email:"
  ask CSR_NAME "Your full legal name (as enrolled):"
  ask CSR_COUNTRY "Two-letter country code (e.g. AU, US):"
  write_env CSR_EMAIL "$CSR_EMAIL"; write_env CSR_NAME "$CSR_NAME"; write_env CSR_COUNTRY "$CSR_COUNTRY"
  (umask 077 && openssl req -new -newkey rsa:2048 -nodes -keyout "$KEY" -out "$CSR" \
    -subj "/emailAddress=$CSR_EMAIL/CN=$CSR_NAME/C=$CSR_COUNTRY" 2>/dev/null)
  printf '  %s✓ created%s %s and %s\n' "$GREEN" "$RESET" "$KEY" "$CSR"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Developer ID Application certificate"
open_url "https://developer.apple.com/account/resources/certificates/add"
step "Choose 'Developer ID Application' (NOT 'Developer ID Installer'), Continue."
step "Profile Type: 'G2 Sub-CA (Xcode 11.4.1 or later)'."
step "Choose File and select: $CSR"
step "Continue, then Download. You get a file like developerID_application.cer."
note "Only the Account Holder can create Developer ID certificates (that's you)."
ask CER_DOWNLOAD "Drag the downloaded .cer file here (or paste its path):"
CER_DOWNLOAD="$(strip_path "$CER_DOWNLOAD")"
CER="$SIGNING_DIR/developer-id.cer"
[[ "$CER_DOWNLOAD" -ef "$CER" ]] || cp "$CER_DOWNLOAD" "$CER"
SUBJECT=$(openssl x509 -inform DER -in "$CER" -noout -subject 2>/dev/null || openssl x509 -in "$CER" -noout -subject)
say "Certificate: $SUBJECT"
[[ "$SUBJECT" == *"Developer ID Application"* ]] || warn "This isn't a 'Developer ID Application' certificate. Recreate it."
[[ "$SUBJECT" == *"$TEAM_ID"* ]] || warn "The certificate doesn't mention Team ID $TEAM_ID. Check stage 3."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Package the certificate for CI (.p12)"
PEM="$SIGNING_DIR/developer-id.pem"; P12="$SIGNING_DIR/developer-id.p12"
CA="$SIGNING_DIR/DeveloperIDG2CA.pem"
openssl x509 -inform DER -in "$CER" -out "$PEM" 2>/dev/null || cp "$CER" "$PEM"
if [[ "$(openssl x509 -in "$PEM" -noout -modulus)" != "$(openssl rsa -in "$KEY" -noout -modulus 2>/dev/null)" ]]; then
  warn "This certificate wasn't made from this PC's private key. Redo stage 5 with $CSR."
  exit 1
fi
note "Fetching Apple's Developer ID G2 intermediate so the chain is complete..."
# Download to a file first: Windows openssl mangles binary DER read from a pipe.
curl -fsSL -o "$SIGNING_DIR/DeveloperIDG2CA.cer" https://www.apple.com/certificateauthority/DeveloperIDG2CA.cer
openssl x509 -inform DER -in "$SIGNING_DIR/DeveloperIDG2CA.cer" -out "$CA"
P12_PASSWORD="$(_existing P12_PASSWORD || openssl rand -base64 24 | tr -d '\n')"
# 3DES/SHA1 packaging: the format macOS's `security import` reliably accepts.
(umask 077 && openssl pkcs12 -export -inkey "$KEY" -in "$PEM" -certfile "$CA" \
  -name "Developer ID Application" -out "$P12" -passout "pass:$P12_PASSWORD" \
  -keypbe PBE-SHA1-3DES -certpbe PBE-SHA1-3DES -macalg sha1)
write_env P12_PASSWORD "$P12_PASSWORD"
printf '  %s✓ created%s %s (key + certificate + Apple intermediate)\n' "$GREEN" "$RESET" "$P12"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Back up offline (do not skip)"
warn "Apple can't re-download your private key. Lose it and you must revoke and"
warn "re-issue, and every user re-grants permissions."
step "Copy the whole folder $SIGNING_DIR to a password manager or an offline drive."
note "It holds developer-id.key, developer-id.p12 and signing.env (incl. the .p12 password)."
until confirm "Backed up?"; do warn "Please back it up before continuing."; done

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect API key (for notarization)"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Open the 'Team Keys' tab. (First time: click 'Request Access' and accept.)"
step "Click + (Generate API Key), name it 'dictatem-notary', Access: Developer, Generate."
step "Copy the 'Issuer ID' shown above the key list."
ask NOTARY_ISSUER_ID "Paste the Issuer ID:"
step "Copy the new key's 'Key ID'."
ask NOTARY_KEY_ID "Paste the Key ID:"
step "Click 'Download' on that key (AuthKey_${NOTARY_KEY_ID}.p8). You can download it only ONCE."
ask P8_DOWNLOAD "Drag the .p8 file here (or paste its path):"
P8_DOWNLOAD="$(strip_path "$P8_DOWNLOAD")"
P8="$SIGNING_DIR/AuthKey_${NOTARY_KEY_ID}.p8"
[[ "$P8_DOWNLOAD" -ef "$P8" ]] || cp "$P8_DOWNLOAD" "$P8"
grep -q "BEGIN PRIVATE KEY" "$P8" || warn "That file doesn't look like a .p8 key."
write_env NOTARY_ISSUER_ID "$NOTARY_ISSUER_ID"; write_env NOTARY_KEY_ID "$NOTARY_KEY_ID"
note "Add the .p8 to your offline backup too."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "GitHub: protected 'release' environment"
say "Secrets go on an environment that only v* tag builds can use, so a branch"
say "or a pull request can never read your signing key."
if confirm "Create/update the '$GH_ENV' environment on $REPO now?"; then
  printf '{"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}' \
    | gh api --method PUT "repos/$REPO/environments/$GH_ENV" --input - >/dev/null
  gh api --method POST "repos/$REPO/environments/$GH_ENV/deployment-branch-policies" \
    -f name='v*' -f type=tag >/dev/null 2>&1 || note "(tag rule v* already present)"
  printf '  %s✓%s environment %s, limited to v* tags\n' "$GREEN" "$RESET" "$GH_ENV"
else
  SKIPPED+=("create the '$GH_ENV' environment (Settings > Environments), limited to v* tags")
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "GitHub: add the secrets"
KEYCHAIN_PASSWORD="$(_existing KEYCHAIN_PASSWORD || openssl rand -base64 24 | tr -d '\n')"
write_env KEYCHAIN_PASSWORD "$KEYCHAIN_PASSWORD"
set_env_secret MACOS_DEVID_P12_BASE64     "$(b64 "$P12")"
set_env_secret MACOS_DEVID_P12_PASSWORD   "$P12_PASSWORD"
set_env_secret MACOS_KEYCHAIN_PASSWORD    "$KEYCHAIN_PASSWORD"
set_env_secret MACOS_NOTARY_KEY_P8_BASE64 "$(b64 "$P8")"
set_env_secret MACOS_NOTARY_KEY_ID        "$NOTARY_KEY_ID"
set_env_secret MACOS_NOTARY_ISSUER_ID     "$NOTARY_ISSUER_ID"
set_env_var    MACOS_TEAM_ID              "$TEAM_ID"
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Tell the build work it can proceed"
say "Posts your Team ID (public, not a secret) on issue #253 so install.sh can pin it."
if confirm "Post the Team ID to #253 now?"; then
  gh issue comment 253 --repo "$REPO" --body "Signing setup done via scripts/wizards/macos-signing-setup.sh. Team ID: \`$TEAM_ID\` (enrollment: Individual). Secrets + MACOS_TEAM_ID are on the \`$GH_ENV\` environment (v* tags only)." >/dev/null \
    && printf '  %s✓ posted%s on #253\n' "$GREEN" "$RESET"
else
  SKIPPED+=("post the Team ID ($TEAM_ID) on issue #253")
fi
note "Next: run the signing spec (#227). Optional: your Mac tester can confirm the"
note "certificate with: security find-identity -v -p codesigning  (after importing the .p12)."
pause

finish
}

run_wizard "$@"; exit
